class Solution:
    def calculate(self, s: str) -> int:
        tokens = []
        i = 0
        while i < len(s):
            if s[i] == " ":
                i += 1
            elif s[i].isdigit():
                num = 0
                while i < len(s) and s[i].isdigit():
                    num = num * 10 + int(s[i])
                    i += 1
                tokens.append(num)
            else:
                tokens.append(s[i])
                i += 1
        i = 1
        while i < len(tokens) - 1:
            if tokens[i] in "*/":
                a, b = tokens[i - 1], tokens[i + 1]
                val = a * b if tokens[i] == "*" else int(a / b)
                tokens[i - 1:i + 2] = [val]
            else:
                i += 2
        result = tokens[0]
        for i in range(1, len(tokens), 2):
            result = result + tokens[i + 1] if tokens[i] == "+" else result - tokens[i + 1]
        return result

solutions.better:
class Solution:
    def calculate(self, s: str) -> int:
        stack = []
        num = 0
        op = "+"
        for ch in s + "+":
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch != " ":
                if op == "+":
                    stack.append(num)
                elif op == "-":
                    stack.append(-num)
                elif op == "*":
                    stack.append(stack.pop() * num)
                else:
                    stack.append(int(stack.pop() / num))
                op = ch
                num = 0
        return sum(stack)

