class Solution:
    def calculate(self, s: str) -> int:
        total = 0
        last = 0
        num = 0
        op = "+"
        for ch in s + "+":
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch != " ":
                if op == "+":
                    total += last
                    last = num
                elif op == "-":
                    total += last
                    last = -num
                elif op == "*":
                    last *= num
                else:
                    last = int(last / num)
                op = ch
                num = 0
        return total + last

